      group0_properties,
      group1_properties,
      group2_properties,
      group3_properties,
      group4_properties,
      group0_created_at,
      group1_created_at,
      group2_created_at,
      group3_created_at,
      group4_created_at,
      person_mode,
      historical_migration,
      coalesce(captured_at, created_at) AS captured_at,
      _timestamp,
      _offset,
      _partition,
      consumer_breadcrumbs
    FROM
      (
        SELECT
          *,
          _timestamp,
          _offset,
          _partition,
          arrayMap(
            i -> (_headers.value[i]),
            arrayFilter(
              i -> ((_headers.name[i]) = 'kafka-consumer-breadcrumbs'),
              arrayEnumerate(_headers.name)
            )
          ) AS consumer_breadcrumbs,
          JSONCleanPostHogEvent(properties, person_properties) AS cleaned
